## Usage Examples

### Basic usage (simple toggle)

```tsx
import { TextExpand } from './components/TextExpand';

function PostCard({ post }) {
  return (
    <TextExpand
      children={post.description}
      maxLines={2}
      seeMoreLabel="Read more"
      showLessLabel="Less"
      onToggle={() => navigate('/post-details')}
    />
  );
}
```

### With custom toggle icon

```tsx
import { Image } from 'react-native';

function ArticleCard({ article }) {
  return (
    <TextExpand
      children={article.summary}
      maxLines={3}
      animated
      toggleContent={() => (
        <View style={styles.iconContainer}>
          {article.isExpanded ? (
            <Image source={{ uri: 'https://icon.less.svg' }} width={16} height={16} />
          ) : (
            <Image source={{ uri: 'https://icon.more.svg' }} width={16} height={16} />
          )}
        </View>
      )}
    />
  );
}
```

### Lazy-loaded / infinite scroll version

